    [0] = {s = {["|1"] = "Talk to Glenne to receive an Ointment.", ["|2"] = "Zone to West Ronfaure and look for Aaveleon at (G-6).", ["|3"] = "Trade the ointment to him, and he'll give back an Ointment Case.", ["|4"] = "Return to Glenne and trade her the Ointment Case to complete the quest and to receive your reward."}},
    [1] = {s = {["|1"] = "Talk to Miageau, and he will have you run an errand for him.", ["|2"] = "Trade 10 gil to Nouveil, who should be nearby Miageau, to receive a Blessed Waterskin.", ["|3"] = "Head to the mouth of the river at (H-5) in East Ronfaure and find a target named the Cheval River.", ["|4"] = "Trade the waterskin to it then return to Miageau, and trade the Cheval Water to him for you reward."}},
    [2] = {s = {["|1"] = "Upon speaking to Rosel in Southern San d'Oria, he will ask you to deliver Receipt for the prince to either Prince Pieuje or Prince Trion in", ["|2"] = "Leave Rosel's Armour Shop and head west into Victory Square.", ["|3"] = "Look for the NPC Guilerme, a guard standing near the bridge into the Chateau.", ["|4"] = "After the cutscene with Guilerme is complete, return to Rosel for your reward."}},
    [3] = {s = {["|1"] = "Talk to Miene by the water, which will start a cut-scene revealing a burglary in process.", ["|2"] = "Talk to Altiret, who asks you to retreive the stolen item.", ["|3"] = "Talk to Miene to obtain a clue, an Eagle Button.", ["|4"] = "(Optional) Several guard and bystander NPCs will have comments about the thief:", ["|5"] = "Head out to West Ronfaure and look for Esca inside a tower at (F-6).", ["|6"] = "Trade the button to her, prompting her to admit she was the thief.", ["|7"] = "After receiving the Gilt Glasses, return them to Altiret for your reward."}},
    [4] = {s = {["|1"] = "Talk to Ailbeche to start the quest for a cutscene.", ["|2"] = "Talk to Ailbeche's father, Exoroche, who can be found in Southern San d'Oria at (K-7) in Helbort's Blade.", ["|3"] = "Return to Ailbeche and talk to him again for a cutscene."}},
