    [7] = {s = {["|1"] = "Start this quest by speaking to Abeaule.", ["|2"] = "Take the Supplies Order to the tower at (I-11) in West Ronfaure and trade them to Phairet.", ["|3"] = "Take the batagreens back to Abeaule for your reward."}},
    [8] = {s = {["|1"] = "Speak with Raimbroy twice to begin quest.", ["|2"] = "Obtain 5 pots of Honey and trade to Raimbroy to end quest."}},
