    [10] = {s = {["|1"] = "Talk to Balasiel, who asks of you a revival tree root.", ["|2"] = "He is located on the upper levels on the walkway.", ["|3"] = "Revival Tree Root can be bought from the auction house (Materials > Alchemy 1) or dropped from Ghost type enemies.", ["|4"] = "Trade the root to him to complete the quest and receive your reward."}},
