    [12] = {s = {["|1"] = "Talk to Fontoumant (in Cargo Room B), who asks you to deliver parcels to various NPCs in Port San d'Oria.", ["|2"] = "Once all parcels are delivered, talk to him again for your reward."}},
    [15] = {s = {["|1"] = "Obtain 3 Lizard Skins", ["|2"] = "Speak with Hanaa Punaa to begin quest and trade her the 3 skins to complete quest."}},
    [16] = {s = {["|1"] = "Make sure you have two slots available in active inventory.", ["|2"] = "Speak with Regine to begin quest and choose the option to look for work.", ["|25"] = "Once all 15 Magicmart Flyers have been distributed, return to Regine and speak with her to end quest.", ["|3"] = "After her story, Magicmart Flyer x15 will given to you.", ["|4"] = "While this quest is active, if you come close to an NPC you need to give a flyer to, a message will appear in /say informing you that \"..."}},
    [18] = {s = {["|1"] = "Speak with Olbergieut to begin quest.", ["|2"] = "Travel to K-8 in La Theine Plateau (its at the tail end wall of the Holla Crag) and look for an NPC named Faurbellant", ["|3"] = "Speak to Faubellant and he will give you Scripture of Water", ["|4"] = "Return to Olbergieut and speak with him to end quest."}},
    [19] = {s = {["|1"] = "Speak to Balasiel to start the quest.", ["|2"] = "Proceed to Ordelle's Caves at map 2 (G-7).", ["|3"] = "Examine the ??? in the pool of water, which will read \"You place your hands into the pool.\" Quickly move towards the middle of the room and", ["|4"] = "Speak to Balasiel to complete the quest."}},
    [20] = {s = {["|1"] = "Speak to Nenne, Southern San d'Oria (F-6)", ["|2"] = "Once you have heard Nenne's story, go into the first house on Watchdog Alley (G-7) and go upstairs into a bedroom and on the table there is", ["|3"] = "Speak to Amaura (G-6) who will ask for Thyme moss.", ["|4"] = "Return the moss to Amaura who will give you Cough medicine.", ["|5"] = "Speak to Nenne who will give you a Scroll of treasure as your reward.", ["|6"] = "The scroll leads you to the signpost at (H-6) in East Ronfaure.", ["|7"] = "Examine the signpost for 3,000 gil."}},
    [23] = {s = {["|1"] = "Trade Black Tiger Fang x3 to Taumila to complete this quest."}},
    [26] = {s = {["|1"] = "Speak to Pagisalis located in the basement of the cathedral to begin this quest.", ["|2"] = "Trade him 2 Beeswax to complete this quest."}},
    [27] = {s = {["|1"] = "Speak to Helbort in Southern San d'Oria (K-7) at the weapon shop after completing Father and Son.", ["|2"] = "Bring the Weapons order to Alexius in Jugner Forest (I-6) near the lake.", ["|3"] = "Return to Helbort to complete the quest."}},
    [29] = {s = {["|1"] = "Speak to Balasiel, who will give you the Book of Tasks containing hints on how to proceed.", ["|2"] = "Speak to Cahaurme (J-9) from (L-8) (In the \"Tower\" above the East Gate) to recieve Book of the East.", ["|3"] = "Speak to Baunise (H-9) from (F-8) (In the \"Tower\" above the West Gate) to receive Book of the West.", ["|4"] = "Go to the dead-end on the map at (E-10) in Davoi and examine the Disused Well to receive Knight's soul.", ["|8"] = "Return to Balasiel to complete the quest."}},
    [30] = {s = {["|1"] = "After speaking with Abeaule head over to Southern San d'Oria (G-6) and speak with Amaura.", ["|2"] = "Amaura requires certain ingredients to brew the medicine, and gives you Amaura's formula which lists them:", ["|3"] = "Gather and trade the listed items to Amaura to get the Cold medicine key item.", ["|4"] = "Deliver the medicine to Abeaule for your reward."}},
    [31] = {s = {["|1"] = "Obtain 3 Black Tiger Hides", ["|2"] = "Speak with Hanaa Punaa to begin quest and trade her the 3 hides to end quest."}},
    [58] = {s = {["|1"] = "(optional) Talk to Kuu Mohzolhi.", ["|2"] = "She won't come out and say it at first, but she would like a Marguerite.", ["|3"] = "Trade it to her to complete the quest."}},
    [59] = {s = {["|1"] = "Speak with Gulmama to obtain quest.", ["|2"] = "Travel to Beaucedine Glacier and enter the ruins of Fei'Yin at (J-4).", ["|3"] = "Defeat Shiva Prime to receive the key item: Whisper of frost", ["|4"] = "Return to Gulmama with the whisper and she will provide several reward options including the ability to summon Shiva (Avatar)."}},
    [60] = {s = {["|1"] = "Speak to Curilla and agree to help her to receive Curilla's bottle.", ["|2"] = "Head to Horlais Peak by going through Yughott Grotto.", ["|3"] = "Once in Horlais Peak, head to the Hot Springs in the springs and check it to get Curilla's bottle again.", ["|4"] = "Return to Curilla for your reward."}},
    [61] = {s = {["|1"] = "Speak to Novalmauge in Bostaunieux Oubliette to begin this quest.", ["|2"] = "Trade Novalmauge a vial of Beastman Blood to complete the quest."}},
    [62] = {s = {["|1"] = "Speak to Chalvatot to begin this quest.", ["|2"] = "Trade Chalvatot a Derfland Humus to complete the quest."}},
    [63] = {s = {["|1"] = "First, zone at (C-7) in Northern San d'Oria.", ["|2"] = "You should be in a watchtower in West Ronfaure now, and Vilatroire should be up ahead after zoning in.", ["|3"] = "Talk to him to activate the quest.", ["|4"] = "After you form a party of two (yourself and one other) with the same allegiance, talk to him again to complete the quest."}},
    [64] = {s = {["|1"] = "First, zone at (C-7) in Northern San d'Oria.", ["|2"] = "You should be in a watchtower in West Ronfaure now, and Vilatroire should be up ahead after zoning in.", ["|3"] = "Talk to him to activate the quest.", ["|4"] = "After you form a party of two (yourself and one other) with the same race, talk to him again to complete the quest."}},
    [65] = {s = {["|1"] = "First, zone at (C-7) in Northern San d'Oria.", ["|2"] = "You should be in a watchtower in West Ronfaure now, and Vilatroire should be up ahead after zoning in.", ["|3"] = "Talk to him to activate the quest.", ["|4"] = "After you form a party of two (yourself and one other) with the same job, talk to him again to complete the quest."}},
    [67] = {s = {["|1"] = "Speak to Portaure in the Cargo Room B near Port San d'Oria Home Point #1 to accept this quest and obtain Brugaire goods.", ["|2"] = "Note: To guarantee going through customs undetected, perform the next step in Jeuno during nighttime hours (18:00-6:00).", ["|3"] = "Travel to Port Jeuno.", ["|4"] = "Speak to Haubijoux at the Air Travel Agency - Arrivals Entrance in Port Jeuno.", ["|5"] = "If you cleared customs, go to the Tenshodo HQ in Lower Jeuno and speak to Yin Pocanakhu (J-8).", ["|6"] = "Return to Portaure for your reward."}},
    [68] = {s = {["|1"] = "Speak to Belgidiveau to begin the quest.", ["|2"] = "Speak to Novalmauge, Bostaunieux Oubliette (G-8).", ["|3"] = "Trade Novalmauge a Dahlia to receive Neutralizer.", ["|4"] = "Return to Belgidiveau to complete this quest."}},
    [69] = {s = {["|1"] = "Speak to Parvipon the tanner in Southern San d'Oria at (E-8) outside of the Leathercraft Guild to begin the quest.", ["|2"] = "Trade Parvipon Rabbit Hide x3 for your reward.", ["|3"] = "Repeat this quest as often as you like, as Parvipon requires a steady flow of hides."}},
    [70] = {s = {["|1"] = "Purchase a Cupboard from the furniture shop in Northern San d'Oria (F-8) and put it in your mog house.", ["|2"] = "Zone out and back into your mog house.", ["|3"] = "Wait some time (between 10-15 real-world minutes).", ["|4"] = "Talk to your Moogle.", ["|7"] = "Bring Calovour a Mistletoe to complete this quest."}},
    [71] = {s = {["|1"] = "Speak with Dauperiat to obtain a Suspicious envelope.", ["|2"] = "Return to Dauperiat, he will now request that you complete a second job for him.", ["|3"] = "If you agree, he requests that you get the floor plans back from the Orcs."}},
    [72] = {s = {["|1"] = "Speak to Vamorcote to begin this quest.", ["|4"] = "Trade the Engraved Key to Vamorcote to complete this quest."}},
    [74] = {s = {["|1"] = "Talk to Femitte, who needs a goldsmithing order fulfilled.", ["|2"] = "Head to Bastok Markets (HP#1), and look for Michea at (F-10).", ["|3"] = "Michea requests a Mythril Ingot.", ["|4"] = "Zone back into Bastok Markets and return to Michea to receive Mythril hearts.", ["|5"] = "Travel back to Southern San d'Oria and talk to Femitte to complete the quest.", ["|6"] = "(Optional) Talk to Michea again for some more lore."}},
    [75] = {s = {["|1"] = "The quest begins from either Joulet (for 'The Competition') or Gallijaux (for 'The Rivalry').", ["|2"] = "Trade whichever NPC you want 10,000 Moat Carp and/or Forest Carp."}},
    [77] = {s = {["|1"] = "Speak to Legata in the Lion Spring's Tavern to begin the quest.", ["|2"] = "Trade her 4 Flint Stones for your reward."}},
    [79] = {s = {["|1"] = "Speak to Maloquedil to begin this quest.", ["|2"] = "Trade him 2 Shaman Garlic to complete this quest."}},
    [80] = {s = {["|1"] = "Mary's Milk is a drop off of Stray Mary in Konschtat Highlands.", ["|2"] = "Can also be bought off an auction house.", ["|3"] = "Obtain one and trade it Paouala your reward."}},
    [81] = {s = {["|1"] = "Speak to Nogelle who asks for 3 Lufet Salts.", ["|2"] = "Lufet Salt drops off River Crabs in West Ronfaure.", ["|3"] = "Trade her the three salts to complete this quest."}},
    [82] = {s = {["|1"] = "Speak with Eperdur at (M-7) in Northern San d'Oria Cathedral.", ["|2"] = "Travel to Gusgen Mines from Konschtat Highlands.", ["|3"] = "Follow these directions to reach the ??? target:", ["|4"] = "Speak with Eperdur again for your reward."}},
    [83] = {s = {["|1"] = "Zone after completing Healing the Land to begin this quest.", ["|2"] = "Speak to Eperdur in Northern San d'Oria (M-7) second level of the Cathedral.", ["|3"] = "Travel to Fei'Yin to open a Treasure Chest.", ["|4"] = "Obtain a Fei'Yin Chest Key by defeating Shadows, Underworld Bats and Ore Golems in that area.", ["|5"] = "Open a treasure chest using either the key or Thief's Tools to obtain the Fei'Yin magic tome.", ["|6"] = "Return to Eperdur to receive your reward."}},
    [84] = {s = {["|1"] = "Speak to Sharzalion in the Lion Springs Tavern (K-6) Southern San d'Oria with Red Mage as your main job.", ["|2"] = "Go to Davoi and fight Purpleflash Brukdok (BLM) at (E-9)/(F-9) to obtain a Davoi Storage Key.", ["|3"] = "Trade the Davoi Storage Key to the targetable Storage Hole that moves throughout the zone randomly at the end/start of each game day.", ["|4"] = "You will obtain the key item Orcish dried food after trading the key.", ["|5"] = "Return to Sharzalion after obtaining the requested item to receive your Fencing Degen."}},
    [85] = {s = {["|1"] = "After completing The Crimson Trial and attaining level 50+ Red Mage, speak to Curilla (I-9) in Chateau d'Oraguille.", ["|2"] = "Next go to the Cathedral (back in Northern San d'Oria, exit the Chateau d'Oraguille) and speak to Pagisalis in the basement.", ["|3"] = "Trade him a Velvet Cloth.", ["|4"] = "Speak to Curilla again.", ["|5"] = "Head to Crawlers' Nest and open a Treasure Chest (blue dots on the map below) using a Nest Chest Key to obtain the key item Crawler blood.", ["|6"] = "On Map 2 at (I-10) examine the ???.", ["|7"] = "Check the ??? again after about a minute to obtain the Warlock's Boots (zoning not required)."}},
    [86] = {s = {["|1"] = "As a Red Mage, Talk to Curilla in Chateau d'Oraguille at (I-9) to start this quest.", ["|2"] = "Head to Southern San d'Oria, find Sharzalion at (K-6) in the Lion Springs Tavern and speak to him.", ["|3"] = "Kill Miser Murphy in Fei'Yin for an Antique Coin.", ["|4"] = "Trade the coin to the Dry Fountain at (H-8) for a cutscene.", ["|5"] = "Head to Southern San d'Oria and speak to Sharzalion and then speak with Daggao who is in the bar as well.", ["|6"] = "Go to Garlaige Citadel (G-8) behind the first banishing gate (map 2) click the Oaken Box in the first room to the left.", ["|7"] = "Kill him for a Nail Puller.", ["|8"] = "Trade the Nail Puller to the same Oaken box for a Cutscene.", ["|9"] = "Zone into Northern San d'Oria for a Cutscene and Warlock's Chapeau."}},
    [87] = {s = {["|1"] = "As a White Mage, talk to Narcheral (M-6) upstairs in the cathedral in Northern San d'Oria to get the quest.", ["|2"] = "Head to (B-8) (Secret Beach) in Valkurm Dunes.", ["|3"] = "Between 18:00 and 5:00 a ??? will appear near the Song Runes.", ["|4"] = "Marchelute drops a Tavnazia Pass.", ["|5"] = "Take the Tavnazia Pass back to Narcheral to complete the quest and receive your Blessed Hammer."}},
    [88] = {s = {["|1"] = "As a White Mage, examine the Door: Prince Regent's Rm in Chateau d'Oraguille at (H-8) to start this quest.", ["|2"] = "Go to Castle Oztroja or Castle Zvahl Keep and kill Yagudo Abbots until a Yagudo Holy Water drops.", ["|3"] = "Yagudo Abbots spawn behind the brass door at (G-8) on map 3.", ["|4"] = "Find a pair of Moccasins", ["|5"] = "Take the pair of Moccasins and the Yagudo Holy Water to Narcheral (M-6) in Northern San d'Oria to complete this quest and obtain your"}},
    [89] = {s = {["|1"] = "Open Door: Prince Regent's Rm in Chateau d'Oraguille at (H-8) to start this quest.", ["|2"] = "Go to Eldieme Necropolis and kill Dark Stalkers until a Tavnazia Bell drops.", ["|3"] = "Travel to Fei'Yin and zone in for a cutscene.", ["|4"] = "Locate the ??? at (G-8) on Map 1.", ["|5"] = "Trade the Tavnazian Mask to Narcheral in the Cathedral upstairs in Northern San d'Oria at (M-6) to receive your Healer's Bliaut."}},
    [90] = {s = {["|1"] = "In order to start this quest, it's necessary to trade back the fishing rod to Ailbeche from the previous quest Father and Son.", ["|2"] = "Speak with Ailbeche near Home Point #2 to begin the quest.", ["|3"] = "Talk to Sobane in (D-6) of Southern San d'Oria.", ["|4"] = "Enter Ordelle's Caves from the entrance in La Theine Plateau position (F-7).", ["|5"] = "Take the first left and walk towards (I-6) on map 2 on to use exit B which will put you on map 1.", ["|6"] = "Examine the Stalagmite in the circular room at (H-10) on map 2 to pop the NM Polevik an Earth Elemental.", ["|7"] = "Defeat the Polevik, then examine the Stalagmite again to obtain the key item: Ordelle whetstone.", ["|8"] = "Return to Ailbeche to end the quest and receive your reward."}},
    [91] = {s = {["|1"] = "Speak with Ailbeche.", ["|10"] = "Return to and speak with Ailbeche again.", ["|11"] = "Speak with Exoroche at Helbort's Blades in Southern San d'Oria (K-7) one last time.", ["|12"] = "Finally, head to Chateau d'Oraguille and select Trion's door (Prince Royal's Rm, H-7) to receive your Gallant Leggings.", ["|2"] = "Talk to Exoroche at Helbort's Blades in Southern San d'Oria (K-7).", ["|3"] = "Return to and speak with Ailbeche again.", ["|4"] = "Trade Ailbeche a Giant Shell Bug.", ["|5"] = "Fish with a rod used for catching big fish in Castle Oztroja using Giant Shell Bug as bait.", ["|6"] = "From the entrance, go through the Brass Door at (I-8) on Map 1.", ["|7"] = "Odontotyrannus (Monster) will be fished up and drops Odontotyrannus.", ["|8"] = "Return Ailbeche and trade them the Odontotyrannus.", ["|9"] = "Head to Selbina and trade Trade Zaldon (H-9), (inside the Fisherman's Guild) the Odontotyrannus and receive the Knight's boots."}},
    [92] = {s = {["|1"] = "Examine the door to Prince Trion's room (Door: Prince Royal's Rm) at Chateau d'Oraguille (H-7) while you are a Paladin for a cutscene.", ["|10"] = "Head to Davoi and locate the Village Well at (G-9).", ["|11"] = "Examine the Village Well will spawn 2 NMs:", ["|12"] = "Trade the Well Weight to the Village Well for a cutscene and (Key Item) Knight's confession.", ["|13"] = "Speak to Ailbeche, Northern San d'Oria (J-9).", ["|14"] = "Travel to Jugner Forest and head for the Maiden's Spring at (E-6).", ["|15"] = "Head back to Chateau d'Oraguille and speak to Prince Trion for your reward.", ["|16"] = "You may additionally talk to Ailbeche, Exoroche, and Vemalpeau for more quest-related dialogue.", ["|2"] = "The rest of this quest can be completed as any job from this point on.", ["|3"] = "Speak to Vemalpeau, Southern San d'Oria (M-7), inside a house.", ["|4"] = "Speak to Najjar, Southern San d'Oria (K-6) inside the Lion Springs Tavern, who will mention (Key Item) Mique's paintbrush.", ["|5"] = "Speak to Ullasa, Southern San d'Oria (B-6) inside the Count's Manor, who will mention (Key Item) Mique's paintbrush.", ["|6"] = "Obtain a Zvahl Coffer Key and trade it to a Treasure Coffer in Castle Zvahl Baileys to get (Key Item) Mique's paintbrush.", ["|7"] = "Return to Vemalpeau.", ["|8"] = "Head to the second story in Vemalpeau's house and examine the ??? on the painting.", ["|9"] = "Speak to Exoroche (K-7) in Helbort's Blades who will tell you how to read the letter."}},
    [93] = {s = {["|1"] = "Speak to Arminibit and Ceraulian in Port San d'Oria (I-9) inside Cargo Room A.", ["|10"] = "Upon defeating the Wyvern, you will receive your reward.", ["|2"] = "Speak to Novalmauge who walks between (F-8) and (G-8) in Bostaunieux Oubliette Map 1 (enter from Northern San d'Oria (I/J-6) HP#2 and then", ["|3"] = "Speak to Morjean in Northern San d'Oria (L-7), within the Cathedral's Manuscript room for a cutscene.", ["|4"] = "If you don't already happen to have some, buy a Pickaxe.", ["|5"] = "Go to the Maze of Shakhrami and trade (/trade) a Pickaxe to an Excavation Point to receive a Wyvern Egg.", ["|6"] = "Return to Morjean and speak to him with the Wyvern Egg in your inventory.", ["|7"] = "Travel to Meriphataud Mountains (K-8) and look for a ??? near the base of Drogaroga's Spine.", ["|8"] = "Speak to Rahal in Chateau d'Oraguille (H-9).", ["|9"] = "Travel to Ghelsba Outpost to find the Hut Door at (F-10/G-10) to enter a BC fight."}},
    [94] = {s = {["|1"] = "Speak to Miaux in Northern San d'Oria (E-6).", ["|2"] = "Examine the ??? in Eastern Altepa Desert in the lower part of (H-8) to spawn Decurio I-III.", ["|3"] = "Examine the ??? after defeating Decurio I-III to receive the Altepa polishing stone.", ["|4"] = "Speak to Miaux again to receive your reward."}},
    [95] = {s = {["|1"] = "Speak to Ceraulian inside Cargo Room A to begin this quest.", ["|10"] = "Examine the ??? at (I-11) to spawn the NM Sturmtiger.", ["|11"] = "Examine the ??? again after Sturmtiger is defeated to get Ranchuriome's legacy.", ["|12"] = "Return to Ceraulian for your reward.", ["|2"] = "Trade him a Gold Hairpin for a cutscene.", ["|3"] = "Wait one minute, then speak to him again.", ["|4"] = "Speak to Miaux, Northern San d'Oria (E-6) to receive a Shiny earring.", ["|5"] = "Speak to Ardea, Bastok Markets (H-8).", ["|8"] = "Next, speak to Esca, West Ronfaure (F-6).", ["|9"] = "Head to the island in Batallia Downs (I-11)."}},
    [96] = {s = {["|1"] = "Speak to Rahal in Chateau d'Oraguille at (H-9) inside the Royal Knight Quarters as a Dragoon to begin this quest.", ["|10"] = "Click the ??? with your wyvern summoned to spawn two NMs; Cleuvarion M Resoaix and Rompaulion S Citalle.", ["|11"] = "Once the NM's are dead, check the ??? again for a cutscene and your reward.", ["|12"] = "Although it is not necessarry, you can return to Ceraulian after defeating the NM's for an additional cutscene.", ["|13"] = "Rahal will also have some additional dialogue for you after the fight.", ["|2"] = "Speak to Ceraulian, Port San d'Oria (I-10) inside Cargo Room A for a cutscene.", ["|3"] = "Speak to Ceraulian once more after the cutscene.", ["|4"] = "Obtain a Kuftal Coffer Key.", ["|5"] = "Return to Rahal and speak to him again.", ["|6"] = "Speak to Balasiel, Southern San d'Oria (F-7)", ["|7"] = "Speak to Rahal again.", ["|8"] = "Head to Temple of Uggalepih for a NM fight.", ["|9"] = "Once inside, head to (F-10) on the first map to find a ???."}},
    [97] = {s = {["|1"] = "Speak to Norejaie to begin this quest.", ["|10"] = "Trusts may be used in this fight.", ["|11"] = "Defeat the Necroplasm and check the ??? again to receive a Indigested stalagmite.", ["|12"] = "Return to Norejaie to complete this quest.", ["|2"] = "Enter Ordelle's Caves from the (F-7) entrance in La Theine Plateau", ["|3"] = "Speak to Rojaireaut (G-3) to have your level capped at 25.", ["|4"] = "Head East through the puddle and follow the path South.", ["|5"] = "Continue to follow the path, eventually you will reach a large room at (G-7).", ["|6"] = "Stick to the wall on the West side and continue South.", ["|7"] = "Before reaching the next tunnel, turn left towards the center of the map.", ["|8"] = "At the North east corner of (G-9) there is a ??? someone in your group will need to examine.", ["|9"] = "When you examine the ??? an NM named Necroplasm will spawn."}},
    [98] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "Go back and speak with Balasiel to receive your reward.", ["|2"] = "Speaking with Balasiel at (F-7) will grant you the key item Weapons Training Guide as well as the Spear of Trials.", ["|3"] = "Breaking the Latent:", ["|6"] = "Trade the Spear of Trials back to Balasiel.", ["|7"] = "Take Silent Oil with you and head to Sea Serpent Grotto.", ["|8"] = "After entering the Grotto, head south into the first large room and take the southwestern tunnel.", ["|9"] = "This fight is against Water Leaper, a pugil."}},
    [99] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "Once inside the Temple, head to the first intersection and go south.", ["|11"] = "This time, when you enter the Temple, you will head to the first intersection and go west.", ["|12"] = "Inside the Den, head south and turn immediately to the east when the room opens up.", ["|13"] = "This fight is against Mokumokuren, a hecteyes.", ["|14"] = "Go back and speak with Novalmauge to receive your reward.", ["|2"] = "Speaking with Novalmauge will grant you the key item Weapons Training Guide as well as the Scythe of Trials.", ["|3"] = "Breaking the Latent", ["|9"] = "Take Silent Oil and Prism Powder with you and head to the Temple of Uggalepih."}},
    [100] = {s = {["|1"] = "Talk to Antreneau, then Thierride.", ["|2"] = "Trade 5 Hare Meat to Thierride to complete the quest."}},
    [101] = {s = {["|1"] = "Start the quest by talking to Aurege (F-3) near Northern San d'Oria Home Point #4, outside of the Carpenter's Guild.", ["|2"] = "(Optional): Talk to Nonterene (I-10) at the Parade Grounds near Victory Arch.", ["|3"] = "Varchet is located in Southern San d'Oria at (L-6) right next to the fountains.", ["|4"] = "You'll need to gamble against him.", ["|5"] = "After winning, return and talk to Aurege for your reward."}},
    [102] = {s = {["|1"] = "Speaking with Curilla will grant you the Weapon training guide as well as the Sapara of Trials.", ["|10"] = "This fight is against Girtablulu, a scorpion.", ["|11"] = "Once you kill it, re-examine the ??? to receive the Annals of Truth.", ["|12"] = "Go back and speak with Curilla to receive your reward.", ["|4"] = "The Bight Uragnite at (K-8) in Ceizak Battlegrounds are a great enemy to break the latent with if you are lv 99+.", ["|5"] = "Trade the Sapara of Trials back to Curilla.", ["|6"] = "You will be instructed to travel to Quicksand Caves.", ["|7"] = "Take Echo Drops and Silent Oil with you.", ["|8"] = "Head to Western Altepa Desert.", ["|9"] = "Once you are behind the Altepa Gate, follow the path to the intersection and go north into the large room."}},
    [105] = {s = {["|1"] = "Speak to Deraquien for a cutscene.", ["|10"] = "Once defeated, click on the ??? again for a cutscene.", ["|11"] = "Return to Phillone for a cutscene.", ["|12"] = "Speak to Narvecaint (F-7) in La Theine Plateau.", ["|13"] = "Return to Phillone to receive your reward.", ["|2"] = "Go to La Theine Plateau and speak with Narvecaint (F-7) at the entrance to Ordelle's Caves for another cutscene.", ["|3"] = "Return to Deraquien and speak to him again.", ["|4"] = "Head to Chateau d'Oraguille and speak to Halver.", ["|5"] = "Speak to Deraquien again.", ["|6"] = "Speak to Phillone (D-7).", ["|7"] = "Go back to speak with Deraquien.", ["|8"] = "Head to Jugner Forest through King Ranperre's Tomb.", ["|9"] = "Click on the ??? at (F-5) between 18:00 and 4:00 to spawn two NMs; Giollemitte B Feroun and Skeleton Esquire."}},
    [107] = {s = {["|1"] = "Speak with Castilchat in Northern San d'Oria (E-7) to begin quest and obtain a Mini Tuning Fork of Ice.", ["|2"] = "You may prepare for the upcoming battle and whenever you are ready, trade Castilchat the tuning fork to be transported to the arena.", ["|4"] = "Defeat Shiva Prime to complete quest."}},
    [108] = {s = {["|1"] = "Speak to Sobane who will request you bring her a Cathedral Tapestry.", ["|2"] = "Trade the Cathedral Tapestry to Sobane.", ["|3"] = "Travel to Selbina and speak to Abelard (G-9).", ["|4"] = "Head to Ordelle's Caves obtain an Ordelle Chest Key off the monsters inside.", ["|5"] = "Use the key on a chest inside to receive Torn-out pages.", ["|6"] = "Return to Abelard.", ["|7"] = "Speak to Sobane to complete this quest."}},
    [109] = {s = {["|1"] = "Speak to Sobane to begin this quest.", ["|10"] = "Return to Sobane for your reward.", ["|2"] = "You will need a Attohwa Ginseng for the next part of the quest.", ["|3"] = "Enter Carpenters' Landing by taking the entrance from Jugner Forest (J-8).", ["|4"] = "Speak to Anguenet (J-10) and trade him the Attohwa Ginseng.", ["|5"] = "Purchase a ticket and board a barge headed for Central Landing via Emfea Way.", ["|6"] = "On the ship, you will find Riche.", ["|9"] = "After the Hematic Cyst is defeated, check the ??? again for a cutscene."}},
    [110] = {s = {["|1"] = "The Rivernewort key item can be found at a ??? located in either Riverne - Site #B01 or Riverne - Site #A01.", ["|2"] = "Once you have acquired the Rivernewort, return to Rouva for your reward; a Page from Miratete's Memoirs."}},
    [112] = {s = {["|2"] = "Speak to Antreneau, Port San d'Oria (G-7) to flag the quest.", ["|4"] = "Head to Uleguerand Range and climb to the top where Jormungand spawns.", ["|5"] = "At (F-9) you will find a slope leading all the way down to the entrance of the zone.", ["|6"] = "Fall down the Southern Slope (the one you see as soon as you zone) and aim for the ledge on your left.", ["|7"] = "Once on the ledge head inside the hole and examine the ???.", ["|8"] = "Trade the Moblin Hotrok to the ??? to complete this quest."}},
    [113] = {s = {["|1"] = "Speak with Amutiyaal to recieve a Red Sentinel badge and begin the quest.", ["|2"] = "Speak with the following people:", ["|3"] = "Once you have spoken to all 20 people, return to Amutiyaal.", ["|5"] = "After joining Salaheem's Sentinels, Alib-Mufalib will offer to teleport you to Aht Urhgan Whitegate."}},
    [114] = {s = {["|1"] = "Speak to Atelloune in Southern San d'Oria at (L-6) for a cutscene to start the quest.", ["|2"] = "Trade her a Ladybug Wing for a cutscene and to receive your reward."}},
    [117] = {s = {["|1"] = "Speak to Vounebariont to begin this quest.", ["|2"] = "Trade Vounebariont 5 Beetle Shells to complete this quest."}},
    [118] = {s = {["|1"] = "Speak to Ramua in Northern San d'Oria (E-3) for a cutscene that begins the quest.", ["|2"] = "Ramua will give you the Timber survey checklist and a Hatchet.", ["|6"] = "Trade these logs to Ramua, for your reward."}},
    [119] = {s = {["|1"] = "Speak to Gondebaud in Southern San d'Oria at (L-6), he will give you the Red institute card.", ["|2"] = "Head to Northern San d'Oria and speak to Excenmille at (D-9)."}},
}
